function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function initialize() {
  const config = { ...$input.first().json };
  ensure(typeof config.previewOnly === 'boolean' && typeof config.createMissingNotes === 'boolean',
    'previewOnly and createMissingNotes must be booleans.');
  ensure(typeof config.obsidianBaseUrl === 'string' &&
    /^https:\/\/(?:[A-Za-z0-9.-]+|\[[A-Fa-f0-9:]+\])(?::[0-9]{1,5})?\/?$/.test(config.obsidianBaseUrl),
    'obsidianBaseUrl must be an HTTPS origin without a path or credentials.');
  config.obsidianBaseUrl = config.obsidianBaseUrl.replace(/\/+$/, '');
  ensure(typeof config.booksFolder === 'string' && /^databases\/[^\r\n]+$/.test(config.booksFolder) &&
    !/[\\*?{}\[\]()!]/.test(config.booksFolder),
    'booksFolder must be a literal folder under databases/.');
  ensure(typeof config.bookTemplatePath === 'string' && /^_templates\/[^\\\r\n]+\.md$/.test(config.bookTemplatePath),
    'bookTemplatePath must be a Markdown template under _templates/.');
  noteUrl(config, `${config.booksFolder}/probe.md`);
  noteUrl(config, config.bookTemplatePath);
  const pieces = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
    timeZone: config.timezone, year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(new Date()).map(item => [item.type, item.value]));
  config.today = `${pieces.year}-${pieces.month}-${pieces.day}`;
  return [{ json: { config, request: { query: 'query ObsidianIdentity { me { id } }' } } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function startLibrary() {
  const data = graph($input.first().json, 'Hardcover identity');
  ensure(Array.isArray(data.me) && data.me.length === 1, 'Hardcover must return exactly your authenticated profile.');
  return [{ json: { config: $('Initialize sync').first().json.config,
    userId: positiveId(data.me[0].id, 'user ID'), cursor: 0, books: [] } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function preparePage() {
  const state = $input.first().json;
  const query = `query ObsidianLibrary($userId: Int!, $cursor: Int!) {
    user_books(where: {user_id: {_eq: $userId}, id: {_gt: $cursor}},
      order_by: {id: asc}, limit: 100) {
      id user_id book_id status_id rating date_added first_started_reading_date last_read_date
      edition { id book_id title asin isbn_10 isbn_13 }
      user_book_reads(order_by: {id: desc}, limit: 1) { id started_at finished_at finished_at_precision }
      book { id title slug literary_type_id alternative_titles
        contributions(order_by: {id: asc}) {
          contribution author { id name } contributor_role { name primary }
        }
      }
    }
  }`;
  return [{ json: { ...state, request: { query, variables: { userId: state.userId, cursor: state.cursor } } },
    pairedItem: { item: 0 } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function collectPage() {
  const state = $('Prepare Hardcover page').item.json;
  const data = graph($input.first().json, 'Hardcover library');
  ensure(Array.isArray(data.user_books), 'Hardcover library must be an array.');
  let cursor = state.cursor;
  for (const record of data.user_books) {
    const id = positiveId(record.id, 'user book ID');
    ensure(id > cursor && record.user_id === state.userId, 'Library pagination returned repeated/out-of-order/wrong-user records.');
    cursor = id;
  }
  return [{ json: { config: state.config, userId: state.userId, cursor,
    books: [...state.books, ...data.user_books], hasMore: data.user_books.length > 0 },
  pairedItem: { item: 0 } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function normalizeLibrary() {
  const state = $input.first().json;
  const seen = new Set();
  const books = state.books.map(record => {
    for (const key of ['id', 'user_id', 'book_id', 'status_id', 'rating', 'date_added',
      'first_started_reading_date', 'last_read_date', 'edition', 'user_book_reads', 'book']) {
      ensure(Object.hasOwn(record, key), `Hardcover omitted requested field ${key}.`);
    }
    const id = positiveId(record.book_id, 'book ID');
    ensure(!seen.has(id), 'Multiple Hardcover library records reference one book; resolve this before syncing.');
    seen.add(id);
    ensure(record.book?.id === id && typeof record.book.title === 'string' && record.book.title.trim(),
      'Hardcover returned a missing/mismatched book.');
    for (const key of ['slug', 'literary_type_id', 'alternative_titles', 'contributions']) {
      ensure(Object.hasOwn(record.book, key), `Hardcover omitted book field ${key}.`);
    }
    const title = article(record.book.title.trim());
    ensure(record.book.literary_type_id == null || Number.isInteger(record.book.literary_type_id),
      'Invalid Hardcover literary classification.');
    ensure(!/[\x00-\x1f\x7f]/.test(title), 'Book title contains control characters.');
    ensure(Array.isArray(record.book.contributions), 'Missing author contributions.');
    const authors = [...new Set(record.book.contributions.filter(credit =>
      credit.contributor_role ? credit.contributor_role.primary === true :
        empty(credit.contribution) || /^(?:author|writer)$/i.test(credit.contribution))
      .map(credit => {
        ensure(typeof credit.author?.name === 'string' && credit.author.name.trim(), 'Missing credited author name.');
        const name = credit.author.name.trim();
        ensure(!/[\[\]|#\x00-\x1f\x7f]/.test(name), 'Author name cannot be represented as a safe wikilink.');
        return name;
      }))];
    const statuses = { 1: 'Not Read', 2: 'In Progress', 3: 'Read', 4: 'Paused', 5: 'Did Not Finish', 6: 'Ignored' };
    ensure(Object.hasOwn(statuses, record.status_id), 'Unknown Hardcover reading status.');
    let rating = record.rating;
    if (rating != null) {
      ensure((typeof rating === 'number' || typeof rating === 'string') && String(rating).trim() !== '' &&
        Number.isFinite(Number(rating)) && Number(rating) >= 0 && Number(rating) <= 5, 'Invalid personal rating.');
      rating = Number(rating);
    }
    ensure(Array.isArray(record.user_book_reads) && record.user_book_reads.length <= 1, 'Unexpected reading-history shape.');
    const read = record.user_book_reads[0];
    if (read) {
      for (const key of ['id', 'started_at', 'finished_at', 'finished_at_precision']) {
        ensure(Object.hasOwn(read, key), `Hardcover omitted reading field ${key}.`);
      }
      positiveId(read.id, 'read-through ID');
    }
    const started = day(read ? read.started_at : record.first_started_reading_date, 'reading start');
    const finished = day(read ? read.finished_at : record.last_read_date, 'reading finish');
    ensure(!started || !finished || started <= finished, 'Reading finishes before it starts.');
    const precision = read?.finished_at_precision ?? null;
    ensure(precision == null || Number.isInteger(precision), 'Invalid reading-date precision.');
    const issues = [];
    const edition = record.edition == null ? null : catalogEdition(record.edition, id, issues);
    if (edition) {
      ensure(Object.hasOwn(edition, 'title'), 'Hardcover omitted edition field title.');
    }
    const slug = record.book.slug;
    ensure(slug == null || (typeof slug === 'string' && !/[\/\\?#\x00-\x1f\x7f]/.test(slug)), 'Unsafe Hardcover slug.');
    const aliases = record.book.alternative_titles;
    ensure(aliases == null || Array.isArray(aliases), 'Unexpected alternative-title format.');
    const titles = [title, edition?.title, ...(aliases || []).filter(value => typeof value === 'string')]
      .filter(value => typeof value === 'string' && value.trim());
    return { id, userBookId: record.id, title, authors, titles,
      status: statuses[record.status_id], rating, started, finished,
      precision: finished ? precision : null, edition, issues,
      added: day(record.date_added, 'library-added date'),
      url: slug ? `https://hardcover.app/books/${encodeURIComponent(slug)}` : null,
      category: ({ 1: 'Fiction', 2: 'Nonfiction' })[record.book.literary_type_id] || null };
  });
  return [{ json: { config: state.config, userId: state.userId, books } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function buildNoteReads() {
  const state = $('Normalize Hardcover library').first().json;
  ensure($input.all().length === 1, 'Obsidian search: expected one full HTTP response, not split result items.');
  const response = $input.first().json;
  const body = jsonResponse(response, 'Obsidian search');
  ensure(Array.isArray(body), 'Obsidian search: expected a JSON array of note results.');
  const seen = new Set();
  const paths = body.map(row => {
    ensure(typeof row.filename === 'string' && row.filename.endsWith('.md'), 'Invalid note search result.');
    const folded = row.filename.normalize('NFC').toLowerCase();
    ensure(!seen.has(folded), 'Duplicate/case-conflicting note paths.');
    seen.add(folded);
    noteUrl(state.config, row.filename);
    return row.filename;
  }).sort();
  return [state.config.bookTemplatePath, ...paths].map((notePath, index) => ({
    json: { path: notePath, kind: index === 0 ? 'template' : 'note', url: noteUrl(state.config, notePath) },
  }));
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function indexNotes() {
  const requests = $('Build Obsidian reads').all();
  const responses = $input.all();
  ensure(requests.length === responses.length, 'Unexpected Obsidian response count.');
  let template;
  const notes = [];
  for (let index = 0; index < responses.length; index++) {
    const request = requests[index].json;
    const response = responses[index].json;
    const body = jsonResponse(response, `Obsidian ${request.path}`);
    ensure(typeof body.content === 'string' && body.frontmatter && typeof body.frontmatter === 'object',
    `Obsidian ${request.path}: expected fresh note JSON.`);
    ensure(body.path === request.path, 'REST response returned a different note path.');
    let inspected;
    try {
      inspected = inspectFrontmatter(body.content, body.frontmatter);
    } catch (error) {
      throw new Error(`${request.path}: ${error.message}`);
    }
    const record = { path: request.path, content: body.content,
      frontmatter: body.frontmatter, meta: inspected.values,
      version: body.version || response.headers?.etag || response.headers?.ETag };
    if (request.kind === 'template') template = record;
    else {
      ensure(typeof record.version === 'string' && record.version, 'Missing file version/ETag for conditional writes.');
      try {
        record.identity = identity(record);
      } catch (error) {
        throw new Error(`${record.path}: ${error.message}`);
      }
      notes.push(record);
    }
  }
  ensure(template, 'The book template was not read.');
  return [{ json: { ...$('Normalize Hardcover library').first().json, template, notes } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function buildLookups() {
  const state = $input.first().json;
  const output = [];
  for (const note of state.notes) {
    const identifier = note.identity;
    if (identifier.id && identifier.isbn) continue;
    const conditions = [];
    if (identifier.asin) conditions.push({ asin: { _eq: identifier.asin } });
    for (const value of isbnVariants(identifier.isbn)) {
      conditions.push({ isbn_10: { _eq: value } }, { isbn_13: { _eq: value } });
    }
    if (!conditions.length) continue;
    output.push({ json: { path: note.path, request: {
      query: `query ObsidianBookIdentity($where: editions_bool_exp!) {
        books(where: {editions: $where}, order_by: {id: asc}, limit: 2) {
          id canonical_id
          editions(where: $where, order_by: {id: asc}, limit: 2) { id book_id asin isbn_10 isbn_13 }
        }
      }`,
      variables: { where: { _or: conditions } },
    } } });
  }
  return output.length ? output : [{ json: { path: null, request: { query: 'query ObsidianLookupSentinel { me { id } }' } } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function prepareUpdates() {
  const requests = $('Build identifier lookups').all();
  const responses = $input.all();
  ensure(requests.length === responses.length, 'Unexpected identity lookup count.');
  const lookups = new Map();
  for (let index = 0; index < responses.length; index++) {
    const data = graph(responses[index].json, 'Hardcover identifier lookup');
    const notePath = requests[index].json.path;
    if (notePath === null) continue;
    ensure(Array.isArray(data.books) && data.books.length <= 2, 'Unexpected catalog lookup response.');
    const matches = data.books.map(book => {
      positiveId(book.id, 'catalog book ID');
      ensure(Object.hasOwn(book, 'canonical_id'), 'Hardcover omitted catalog canonical_id.');
      if (book.canonical_id != null) positiveId(book.canonical_id, 'canonical book ID');
      ensure(Array.isArray(book.editions) && book.editions.length <= 2, 'Unexpected matched editions.');
      const issues = [];
      const editions = book.editions.map(edition => catalogEdition(edition, book.id, issues));
      return { ...book, editions, issues };
    });
    lookups.set(notePath, matches);
  }
  return planLibrary($('Index Obsidian notes').first().json, lookups).map(json => ({ json }));
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function preview() {
  return $input.all().map(item => {
    const { config, action, path, bookId, changes, issues, blockers, note } = item.json;
    return { json: { previewOnly: config.previewOnly, action, path, bookId, changes, issues,
      blocked: blockers.length > 0, conflicts: blockers,
      note: note || (config.previewOnly ? 'Preview only; no note was written.' : 'No write required.') } };
  });
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function verify() {
  const expected = $('Write enabled?').all(0);
  const actual = $input.all();
  ensure(expected.length === actual.length, 'Unexpected read-back response count.');
  return actual.map((response, index) => {
    const plan = expected[index].json;
    const body = httpBody(response.json, `Obsidian read-back ${plan.path}`);
    ensure(body === plan.proposedContent,
      `${plan.path}: persisted content differs from the proposal; inspect concurrent/Seafile edits before rerunning.`);
    return { json: { path: plan.path, bookId: plan.bookId, action: plan.action,
      verified: true, changes: plan.changes, issues: plan.issues } };
  });
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function initialize() {
  const config = { ...$input.first().json };
  ensure(typeof config.previewOnly === 'boolean' && typeof config.createMissingNotes === 'boolean',
    'previewOnly and createMissingNotes must be booleans.');
  ensure(typeof config.obsidianBaseUrl === 'string' &&
    /^https:\/\/(?:[A-Za-z0-9.-]+|\[[A-Fa-f0-9:]+\])(?::[0-9]{1,5})?\/?$/.test(config.obsidianBaseUrl),
    'obsidianBaseUrl must be an HTTPS origin without a path or credentials.');
  config.obsidianBaseUrl = config.obsidianBaseUrl.replace(/\/+$/, '');
  ensure(typeof config.booksFolder === 'string' && /^databases\/[^\r\n]+$/.test(config.booksFolder) &&
    !/[\\*?{}\[\]()!]/.test(config.booksFolder),
    'booksFolder must be a literal folder under databases/.');
  ensure(typeof config.bookTemplatePath === 'string' && /^_templates\/[^\\\r\n]+\.md$/.test(config.bookTemplatePath),
    'bookTemplatePath must be a Markdown template under _templates/.');
  noteUrl(config, `${config.booksFolder}/probe.md`);
  noteUrl(config, config.bookTemplatePath);
  const pieces = Object.fromEntries(new Intl.DateTimeFormat('en-CA', {
    timeZone: config.timezone, year: 'numeric', month: '2-digit', day: '2-digit',
  }).formatToParts(new Date()).map(item => [item.type, item.value]));
  config.today = `${pieces.year}-${pieces.month}-${pieces.day}`;
  return [{ json: { config, request: { query: 'query ObsidianIdentity { me { id } }' } } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function startLibrary() {
  const data = graph($input.first().json, 'Hardcover identity');
  ensure(Array.isArray(data.me) && data.me.length === 1, 'Hardcover must return exactly your authenticated profile.');
  return [{ json: { config: $('Initialize sync').first().json.config,
    userId: positiveId(data.me[0].id, 'user ID'), cursor: 0, books: [] } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function preparePage() {
  const state = $input.first().json;
  const query = `query ObsidianLibrary($userId: Int!, $cursor: Int!) {
    user_books(where: {user_id: {_eq: $userId}, id: {_gt: $cursor}},
      order_by: {id: asc}, limit: 100) {
      id user_id book_id status_id rating date_added first_started_reading_date last_read_date
      edition { id book_id title asin isbn_10 isbn_13 }
      user_book_reads(order_by: {id: desc}, limit: 1) { id started_at finished_at finished_at_precision }
      book { id title slug literary_type_id alternative_titles
        contributions(order_by: {id: asc}) {
          contribution author { id name } contributor_role { name primary }
        }
      }
    }
  }`;
  return [{ json: { ...state, request: { query, variables: { userId: state.userId, cursor: state.cursor } } },
    pairedItem: { item: 0 } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function collectPage() {
  const state = $('Prepare Hardcover page').item.json;
  const data = graph($input.first().json, 'Hardcover library');
  ensure(Array.isArray(data.user_books), 'Hardcover library must be an array.');
  let cursor = state.cursor;
  for (const record of data.user_books) {
    const id = positiveId(record.id, 'user book ID');
    ensure(id > cursor && record.user_id === state.userId, 'Library pagination returned repeated/out-of-order/wrong-user records.');
    cursor = id;
  }
  return [{ json: { config: state.config, userId: state.userId, cursor,
    books: [...state.books, ...data.user_books], hasMore: data.user_books.length > 0 },
  pairedItem: { item: 0 } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function normalizeLibrary() {
  const state = $input.first().json;
  const seen = new Set();
  const books = state.books.map(record => {
    for (const key of ['id', 'user_id', 'book_id', 'status_id', 'rating', 'date_added',
      'first_started_reading_date', 'last_read_date', 'edition', 'user_book_reads', 'book']) {
      ensure(Object.hasOwn(record, key), `Hardcover omitted requested field ${key}.`);
    }
    const id = positiveId(record.book_id, 'book ID');
    ensure(!seen.has(id), 'Multiple Hardcover library records reference one book; resolve this before syncing.');
    seen.add(id);
    ensure(record.book?.id === id && typeof record.book.title === 'string' && record.book.title.trim(),
      'Hardcover returned a missing/mismatched book.');
    for (const key of ['slug', 'literary_type_id', 'alternative_titles', 'contributions']) {
      ensure(Object.hasOwn(record.book, key), `Hardcover omitted book field ${key}.`);
    }
    const title = article(record.book.title.trim());
    ensure(record.book.literary_type_id == null || Number.isInteger(record.book.literary_type_id),
      'Invalid Hardcover literary classification.');
    ensure(!/[\x00-\x1f\x7f]/.test(title), 'Book title contains control characters.');
    ensure(Array.isArray(record.book.contributions), 'Missing author contributions.');
    const authors = [...new Set(record.book.contributions.filter(credit =>
      credit.contributor_role ? credit.contributor_role.primary === true :
        empty(credit.contribution) || /^(?:author|writer)$/i.test(credit.contribution))
      .map(credit => {
        ensure(typeof credit.author?.name === 'string' && credit.author.name.trim(), 'Missing credited author name.');
        const name = credit.author.name.trim();
        ensure(!/[\[\]|#\x00-\x1f\x7f]/.test(name), 'Author name cannot be represented as a safe wikilink.');
        return name;
      }))];
    const statuses = { 1: 'Not Read', 2: 'In Progress', 3: 'Read', 4: 'Paused', 5: 'Did Not Finish', 6: 'Ignored' };
    ensure(Object.hasOwn(statuses, record.status_id), 'Unknown Hardcover reading status.');
    let rating = record.rating;
    if (rating != null) {
      ensure((typeof rating === 'number' || typeof rating === 'string') && String(rating).trim() !== '' &&
        Number.isFinite(Number(rating)) && Number(rating) >= 0 && Number(rating) <= 5, 'Invalid personal rating.');
      rating = Number(rating);
    }
    ensure(Array.isArray(record.user_book_reads) && record.user_book_reads.length <= 1, 'Unexpected reading-history shape.');
    const read = record.user_book_reads[0];
    if (read) {
      for (const key of ['id', 'started_at', 'finished_at', 'finished_at_precision']) {
        ensure(Object.hasOwn(read, key), `Hardcover omitted reading field ${key}.`);
      }
      positiveId(read.id, 'read-through ID');
    }
    const started = day(read ? read.started_at : record.first_started_reading_date, 'reading start');
    const finished = day(read ? read.finished_at : record.last_read_date, 'reading finish');
    ensure(!started || !finished || started <= finished, 'Reading finishes before it starts.');
    const precision = read?.finished_at_precision ?? null;
    ensure(precision == null || Number.isInteger(precision), 'Invalid reading-date precision.');
    const issues = [];
    const edition = record.edition == null ? null : catalogEdition(record.edition, id, issues);
    if (edition) {
      ensure(Object.hasOwn(edition, 'title'), 'Hardcover omitted edition field title.');
    }
    const slug = record.book.slug;
    ensure(slug == null || (typeof slug === 'string' && !/[\/\\?#\x00-\x1f\x7f]/.test(slug)), 'Unsafe Hardcover slug.');
    const aliases = record.book.alternative_titles;
    ensure(aliases == null || Array.isArray(aliases), 'Unexpected alternative-title format.');
    const titles = [title, edition?.title, ...(aliases || []).filter(value => typeof value === 'string')]
      .filter(value => typeof value === 'string' && value.trim());
    return { id, userBookId: record.id, title, authors, titles,
      status: statuses[record.status_id], rating, started, finished,
      precision: finished ? precision : null, edition, issues,
      added: day(record.date_added, 'library-added date'),
      url: slug ? `https://hardcover.app/books/${encodeURIComponent(slug)}` : null,
      category: ({ 1: 'Fiction', 2: 'Nonfiction' })[record.book.literary_type_id] || null };
  });
  return [{ json: { config: state.config, userId: state.userId, books } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function buildNoteReads() {
  const state = $('Normalize Hardcover library').first().json;
  ensure($input.all().length === 1, 'Obsidian search: expected one full HTTP response, not split result items.');
  const response = $input.first().json;
  const body = jsonResponse(response, 'Obsidian search');
  ensure(Array.isArray(body), 'Obsidian search: expected a JSON array of note results.');
  const seen = new Set();
  const paths = body.map(row => {
    ensure(typeof row.filename === 'string' && row.filename.endsWith('.md'), 'Invalid note search result.');
    const folded = row.filename.normalize('NFC').toLowerCase();
    ensure(!seen.has(folded), 'Duplicate/case-conflicting note paths.');
    seen.add(folded);
    noteUrl(state.config, row.filename);
    return row.filename;
  }).sort();
  return [state.config.bookTemplatePath, ...paths].map((notePath, index) => ({
    json: { path: notePath, kind: index === 0 ? 'template' : 'note', url: noteUrl(state.config, notePath) },
  }));
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function indexNotes() {
  const requests = $('Build Obsidian reads').all();
  const responses = $input.all();
  ensure(requests.length === responses.length, 'Unexpected Obsidian response count.');
  let template;
  const notes = [];
  for (let index = 0; index < responses.length; index++) {
    const request = requests[index].json;
    const response = responses[index].json;
    const body = jsonResponse(response, `Obsidian ${request.path}`);
    ensure(typeof body.content === 'string' && body.frontmatter && typeof body.frontmatter === 'object',
    `Obsidian ${request.path}: expected fresh note JSON.`);
    ensure(body.path === request.path, 'REST response returned a different note path.');
    let inspected;
    try {
      inspected = inspectFrontmatter(body.content, body.frontmatter);
    } catch (error) {
      throw new Error(`${request.path}: ${error.message}`);
    }
    const record = { path: request.path, content: body.content,
      frontmatter: body.frontmatter, meta: inspected.values,
      version: body.version || response.headers?.etag || response.headers?.ETag };
    if (request.kind === 'template') template = record;
    else {
      ensure(typeof record.version === 'string' && record.version, 'Missing file version/ETag for conditional writes.');
      try {
        record.identity = identity(record);
      } catch (error) {
        throw new Error(`${record.path}: ${error.message}`);
      }
      notes.push(record);
    }
  }
  ensure(template, 'The book template was not read.');
  return [{ json: { ...$('Normalize Hardcover library').first().json, template, notes } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function buildLookups() {
  const state = $input.first().json;
  const output = [];
  for (const note of state.notes) {
    const identifier = note.identity;
    if (identifier.id && identifier.isbn) continue;
    const conditions = [];
    if (identifier.asin) conditions.push({ asin: { _eq: identifier.asin } });
    for (const value of isbnVariants(identifier.isbn)) {
      conditions.push({ isbn_10: { _eq: value } }, { isbn_13: { _eq: value } });
    }
    if (!conditions.length) continue;
    output.push({ json: { path: note.path, request: {
      query: `query ObsidianBookIdentity($where: editions_bool_exp!) {
        books(where: {editions: $where}, order_by: {id: asc}, limit: 2) {
          id canonical_id
          editions(where: $where, order_by: {id: asc}, limit: 2) { id book_id asin isbn_10 isbn_13 }
        }
      }`,
      variables: { where: { _or: conditions } },
    } } });
  }
  return output.length ? output : [{ json: { path: null, request: { query: 'query ObsidianLookupSentinel { me { id } }' } } }];
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function prepareUpdates() {
  const requests = $('Build identifier lookups').all();
  const responses = $input.all();
  ensure(requests.length === responses.length, 'Unexpected identity lookup count.');
  const lookups = new Map();
  for (let index = 0; index < responses.length; index++) {
    const data = graph(responses[index].json, 'Hardcover identifier lookup');
    const notePath = requests[index].json.path;
    if (notePath === null) continue;
    ensure(Array.isArray(data.books) && data.books.length <= 2, 'Unexpected catalog lookup response.');
    const matches = data.books.map(book => {
      positiveId(book.id, 'catalog book ID');
      ensure(Object.hasOwn(book, 'canonical_id'), 'Hardcover omitted catalog canonical_id.');
      if (book.canonical_id != null) positiveId(book.canonical_id, 'canonical book ID');
      ensure(Array.isArray(book.editions) && book.editions.length <= 2, 'Unexpected matched editions.');
      const issues = [];
      const editions = book.editions.map(edition => catalogEdition(edition, book.id, issues));
      return { ...book, editions, issues };
    });
    lookups.set(notePath, matches);
  }
  return planLibrary($('Index Obsidian notes').first().json, lookups).map(json => ({ json }));
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function preview() {
  return $input.all().map(item => {
    const { config, action, path, bookId, changes, issues, blockers, note } = item.json;
    return { json: { previewOnly: config.previewOnly, action, path, bookId, changes, issues,
      blocked: blockers.length > 0, conflicts: blockers,
      note: note || (config.previewOnly ? 'Preview only; no note was written.' : 'No write required.') } };
  });
})();

function isSyncField(key) {
  return /^(?:hardcover_|sparkyfitness_|kindle-)/i.test(key);
}

function isSyncObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  // n8n secure mode stubs prototype inspection; validate record shape instead.
  if (Object.prototype.toString.call(value) !== '[object Object]') return false;
  if (!Object.hasOwn(value, 'constructor') && value.constructor !== undefined &&
      (typeof value.constructor !== 'function' || value.constructor.name !== 'Object')) return false;
  for (const key in value) {
    if (!Object.hasOwn(value, key)) return false;
  }
  return true;
}

function syncJson(value) {
  const normalize = item => {
    if (item === null || typeof item === 'string' || typeof item === 'boolean') return item;
    if (typeof item === 'number' && Number.isFinite(item)) return item;
    if (Array.isArray(item)) return item.map(normalize);
    if (isSyncObject(item)) {
      return Object.fromEntries(Object.keys(item).sort().map(key => [key, normalize(item[key])]));
    }
    throw new Error('External-sync metadata must contain only JSON values.');
  };
  return JSON.stringify(normalize(value)).replace(/</g, '\\u003c').replace(/>/g, '\\u003e');
}

function validateSyncProperties(properties) {
  if (!isSyncObject(properties)) {
    throw new Error('External-sync properties must be a JSON object.');
  }
  const seen = new Set();
  for (const key of Object.keys(properties)) {
    if (!isSyncField(key) || seen.has(key.toLowerCase())) {
      throw new Error(`Unknown or case-conflicting external-sync property: ${key}`);
    }
    seen.add(key.toLowerCase());
  }
  syncJson(properties);
  return properties;
}

function readSyncMetadata(content) {
  const marker = '<!-- external-sync';
  const count = content.split(marker).length - 1;
  if (!count) return { properties: {}, start: -1, end: -1 };
  const matches = [...content.matchAll(/^<!-- external-sync\r?\n([\s\S]*?)\r?\n-->(?=\r?\n|$)/gm)];
  if (count !== 1 || matches.length !== 1) {
    throw new Error('Malformed or repeated external-sync comment; refusing to edit.');
  }
  const match = matches[0];
  const before = content.slice(0, match.index);
  const opening = /^\uFEFF?---[ \t]*\r?\n/.exec(content);
  const closing = opening && /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(content.slice(opening[0].length));
  if (opening && (!closing || match.index < opening[0].length + closing.index + closing[0].length)) {
    throw new Error('External-sync comments must be outside frontmatter.');
  }
  let fence = null;
  for (const line of before.split(/\r?\n/)) {
    const token = /^ {0,3}(`{3,}|~{3,})(.*)$/.exec(line);
    if (!token) continue;
    if (!fence) fence = { character: token[1][0], length: token[1].length };
    else if (token[1][0] === fence.character && token[1].length >= fence.length && !token[2].trim()) fence = null;
  }
  if (fence || before.lastIndexOf('<!--') > before.lastIndexOf('-->')) {
    throw new Error('External-sync comments must not be inside code fences or other comments.');
  }
  let payload;
  try {
    payload = JSON.parse(match[1]);
  } catch (error) {
    throw new Error(`Invalid external-sync JSON: ${error.message}`);
  }
  if (!payload || payload.version !== 1 || Object.keys(payload).sort().join(',') !== 'properties,version') {
    throw new Error('Unsupported external-sync schema; expected version 1 and properties.');
  }
  return { properties: validateSyncProperties(payload.properties), start: match.index,
    end: match.index + match[0].length };
}

function mergeSyncProperties(content, metadata) {
  const properties = { ...readSyncMetadata(content).properties };
  for (const [key, value] of Object.entries(metadata)) {
    if (!isSyncField(key)) continue;
    const existing = Object.keys(properties).find(name => name.toLowerCase() === key.toLowerCase());
    if (existing && syncJson(properties[existing]) !== syncJson(value)) {
      throw new Error(`Legacy frontmatter and external-sync comment disagree for ${key}.`);
    }
    if (!existing) properties[key] = value;
  }
  return validateSyncProperties(properties);
}

function writeSyncMetadata(content, properties) {
  validateSyncProperties(properties);
  const previous = readSyncMetadata(content);
  if (!Object.keys(properties).length && previous.start < 0) return content;
  const eol = content.includes('\r\n') ? '\r\n' : '\n';
  const comment = `<!-- external-sync${eol}${syncJson({ version: 1, properties })}${eol}-->`;
  const updated = previous.start >= 0
    ? content.slice(0, previous.start) + comment + content.slice(previous.end)
    : content + (content.endsWith(eol + eol) ? '' : content.endsWith('\n') ? eol : eol + eol) + comment + eol;
  readSyncMetadata(updated);
  return updated;
}

function ensure(value, message) {
  if (!value) throw new Error(message);
}

function empty(value) {
  return value == null || (typeof value === 'string' && ['', 'null'].includes(value.trim().toLowerCase())) ||
    (Array.isArray(value) && value.length === 0);
}

function positiveId(value, label) {
  const number = typeof value === 'string' && /^[1-9][0-9]*$/.test(value) ? Number(value) : value;
  ensure(Number.isSafeInteger(number) && number > 0, `${label}: expected a positive integer.`);
  return number;
}

function day(value, label) {
  if (value == null) return null;
  ensure(typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) &&
    Number.isFinite(Date.parse(`${value}T00:00:00Z`)) &&
    new Date(`${value}T00:00:00Z`).toISOString().slice(0, 10) === value, `${label}: invalid calendar date.`);
  return value;
}

function httpBody(response, label) {
  ensure(response?.statusCode === 200,
    `${label}: expected HTTP 200, received ${response?.statusCode ?? 'no status'}. Include response headers and status must remain enabled.`);
  const hasBody = Object.hasOwn(response, 'body');
  const hasData = Object.hasOwn(response, 'data');
  ensure(hasBody || hasData, `${label}: missing HTTP response content; expected n8n's body or data field.`);
  ensure(!(hasBody && hasData), `${label}: ambiguous HTTP response; both body and data fields are present.`);
  const body = hasBody ? response.body : response.data;
  ensure(!(body && typeof body === 'object' && Object.hasOwn(body, '_readableState')),
    `${label}: received an undecoded HTTP stream. Set the HTTP node's Response Format to Autodetect, keep response headers and status enabled, then rerun the HTTP request.`);
  return body;
}

function jsonResponse(response, label) {
  let body = httpBody(response, label);
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (error) {
      if (!(error instanceof SyntaxError)) throw error;
      throw new Error(`${label}: response body is not valid JSON. Check the endpoint, response Content-Type and proxy routing.`);
    }
  }
  ensure(body !== null && typeof body === 'object', `${label}: expected a decoded JSON response.`);
  return body;
}

function graph(response, label) {
  const body = jsonResponse(response, label);
  ensure(!body.errors || (Array.isArray(body.errors) && body.errors.length === 0),
    `${label}: GraphQL errors: ${JSON.stringify(body.errors)}`);
  ensure(body.data && typeof body.data === 'object', `${label}: missing GraphQL data.`);
  return body.data;
}

function article(title) {
  return title.replace(/^(.*),\s*(The|An|A)(:.*)?$/i,
    (_, base, word, subtitle) => `${word[0].toUpperCase()}${word.slice(1).toLowerCase()} ${base}${subtitle || ''}`);
}

function normalized(value) {
  return String(value).normalize('NFKD').replace(/\p{M}/gu, '').toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
}

function titleKey(value) {
  return normalized(article(value));
}

function authorKey(value) {
  return normalized(value.replace(/^\[\[|\]\]$/g, '').split('|')[0]).split(/\s+/).sort().join(' ');
}

function authorKeys(values) {
  return [...new Set(values.map(authorKey))].sort();
}

function authorText(authors) {
  if (authors.length <= 2) return authors.join(' and ');
  return `${authors.slice(0, -1).join(', ')}, and ${authors.at(-1)}`;
}

function noteUrl(config, notePath) {
  ensure(notePath.startsWith(`${config.booksFolder}/`) || notePath === config.bookTemplatePath,
    `Out-of-scope note path: ${notePath}`);
  ensure(!notePath.split('/').some(part => !part || part === '.' || part === '..' || part.startsWith('.')) &&
    !/[\\\x00-\x1f\x7f]/.test(notePath), `Unsafe note path: ${notePath}`);
  return `${config.obsidianBaseUrl}/vault/${notePath.split('/').map(encodeURIComponent).join('/')}`;
}

function parts(content) {
  ensure(typeof content === 'string', 'Expected Markdown text.');
  const bom = content.startsWith('\uFEFF') ? '\uFEFF' : '';
  const text = content.slice(bom.length);
  const eol = text.includes('\r\n') ? '\r\n' : '\n';
  const opening = /^---[ \t]*\r?\n/.exec(text);
  if (!opening) {
    ensure(text.trim() !== '---', 'Unclosed YAML frontmatter.');
    return { prefix: `${bom}---${eol}`, yaml: '', closing: `---${eol}`, tail: text, eol, present: false };
  }
  const rest = text.slice(opening[0].length);
  const closing = /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/m.exec(rest);
  ensure(closing, 'Unclosed YAML frontmatter.');
  return { prefix: bom + opening[0], yaml: rest.slice(0, closing.index), closing: closing[0],
    tail: rest.slice(closing.index + closing[0].length), eol, present: true };
}

function scalarWithComment(raw) {
  let quote = null;
  let escaped = false;
  const start = raw.search(/\S/);
  const flow = /^[\[{]/.test(raw.trimStart());
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quote === '"') {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quote = null;
    } else if (quote === "'") {
      if (character === "'" && raw[index + 1] === "'") index++;
      else if (character === "'") quote = null;
    } else if ((character === '"' || character === "'") && (index === start || flow)) {
      quote = character;
    } else if (character === '#' && (index === 0 || /\s/.test(raw[index - 1]))) {
      return { raw: raw.slice(0, index).trim(), comment: raw.slice(index) };
    }
  }
  ensure(!quote, 'Unclosed YAML scalar quote.');
  return { raw: raw.trim(), comment: '' };
}

function scalar(raw) {
  const value = scalarWithComment(raw).raw;
  if (/^(?:null|~)?$/i.test(value)) return null;
  if (value.startsWith('"') || value.startsWith('[') || value.startsWith('{')) {
    let result;
    try {
      result = JSON.parse(value);
    } catch (error) {
      throw new Error(`Unsupported YAML flow/quoted value; use JSON-compatible values: ${error.message}`);
    }
    return result;
  }
  if (value.startsWith("'")) {
    ensure(/^'(?:[^']|'')*'$/.test(value), 'Unsupported YAML single-quoted scalar.');
    return value.slice(1, -1).replace(/''/g, "'");
  }
  ensure(!/^[&*!>|%@`]/.test(value) && !/:\s/.test(value),
    'Unsupported YAML anchor, alias, tag, or structured scalar.');
  if (/^(?:true|false)$/i.test(value)) return value.toLowerCase() === 'true';
  if (/^[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?$/.test(value)) {
    ensure(Number.isFinite(Number(value)), 'Non-finite YAML number.');
    return Number(value);
  }
  return value;
}

function knownFields() {
  return ['author', 'title', 'asin', 'isbn', 'source', 'category', 'topic', 'status', 'rating',
    'started', 'finished', 'hardcover_finished_precision', 'hardcover_id', 'hardcover_user_id',
    'hardcover_user_book_id', 'hardcover_url', 'hardcover_added', 'hardcover_edition_id',
    'kindle-sync', 'kindle-asin', 'kindle-title', 'kindle-author'];
}

function kindleMap(lines) {
  const value = Object.create(null);
  for (let index = 0; index < lines.length;) {
    const item = /^([ \t]+)([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)(.*?)(?:\r?\n)?$/.exec(lines[index]);
    ensure(item && !Object.hasOwn(value, item[2]), 'Unsupported nested Kindle metadata.');
    let end = index + 1;
    while (end < lines.length && /^[ \t]*/.exec(lines[end])[0].length > item[1].length) end++;
    const tail = lines.slice(index + 1, end);
    if (scalarWithComment(item[3]).raw === '>-') {
      ensure(tail.length > 0, 'Empty folded Kindle scalar.');
      const indentation = /^[ \t]*/.exec(tail[0])[0].length;
      ensure(tail.every(line => /^[ \t]*/.exec(line)[0].length === indentation),
        'Complex folded Kindle scalars need manual normalization.');
      value[item[2]] = tail.map(line => line.slice(indentation).replace(/\r?\n$/, '')).join(' ');
    } else {
      ensure(tail.length === 0, 'Unsupported multiline Kindle value.');
      value[item[2]] = scalar(item[3]);
    }
    index = end;
  }
  return value;
}

function inspectFrontmatter(content, metadata) {
  ensure(metadata && typeof metadata === 'object' && !Array.isArray(metadata), 'Missing parsed Obsidian frontmatter.');
  const block = parts(content);
  const known = new Set([...knownFields(),
    ...Object.keys(metadata).filter(isSyncField).map(key => key.toLowerCase())]);
  const values = Object.create(null);
  for (const [key, value] of Object.entries(metadata)) {
    const folded = key.toLowerCase();
    ensure(!Object.hasOwn(values, folded), `Case-conflicting frontmatter property: ${key}`);
    values[folded] = value;
  }
  const lines = block.yaml.match(/[^\n]*(?:\n|$)/g)?.filter(Boolean) || [];
  const entries = Object.create(null);
  const allKeys = new Set();
  for (const line of lines) {
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|\r?\n|$)/.exec(line);
    if (match) {
      const key = match[1].toLowerCase();
      ensure(!allKeys.has(key), `Duplicate YAML property: ${key}`);
      allKeys.add(key);
    }
  }
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index].replace(/\r?\n$/, '');
    if (/^(?:[ \t]|#|$)/.test(line) || /^-[ \t]/.test(line)) continue;
    ensure(!/^(?:[{\[?]|<<[ \t]*:)/.test(line), 'Flow/explicit/merged YAML frontmatter is not supported.');
    const quoted = /^(?:"([^"]+)"|'([^']+)')[ \t]*:/.exec(line);
    if (quoted) {
      ensure(!known.has((quoted[1] || quoted[2]).toLowerCase()), 'Managed YAML property names must be unquoted.');
      continue;
    }
    const match = /^([A-Za-z_][A-Za-z0-9_-]*):(?:[ \t]|$)/.exec(line);
    if (!match) {
      ensure(/^[^:#][^:]*:(?:[ \t]|$)/.test(line), 'Unsupported top-level YAML key.');
      continue;
    }
    const key = match[1].toLowerCase();
    if (!known.has(key)) continue;
    let end = index + 1;
    while (end < lines.length &&
      /^(?:[ \t]|#|-[ \t]|$)/.test(lines[end].replace(/\r?\n$/, ''))) end++;
    const continuation = lines.slice(index + 1, end).filter(value => !/^\s*(?:#.*)?$/.test(value));
    const raw = line.slice(match[1].length + 1);
    const first = scalarWithComment(raw);
    let value;
    if (first.raw === '' && continuation.length) {
      if (continuation.every(value => /^\s*-[ \t]+/.test(value))) {
        value = continuation.map(value => scalar(value.replace(/^\s*-[ \t]+/, '').replace(/\r?\n$/, '')));
      } else {
        ensure(key === 'kindle-sync', `Unsupported structured/multiline value: ${key}`);
        value = kindleMap(continuation);
      }
    } else {
      ensure(continuation.length === 0, `Unsupported continuation for ${key}`);
      value = scalar(raw);
    }
    ensure(Object.hasOwn(values, key) && JSON.stringify(value) === JSON.stringify(values[key]),
      `Obsidian metadata cache disagrees with raw YAML for ${key}; wait for indexing and rerun.`);
    entries[key] = { start: index, end, spelling: match[1], comment: first.comment };
  }
  for (const key of known) {
    ensure(!Object.hasOwn(values, key) || Object.hasOwn(entries, key),
      `Missing/quoted/stale YAML property: ${key}`);
  }
  for (const [key, value] of Object.entries(mergeSyncProperties(content, metadata))) {
    values[key.toLowerCase()] = value;
  }
  return { block, lines, entries, values };
}

function splice(content, metadata, updates) {
  const inspected = inspectFrontmatter(content, metadata);
  const { block, lines, entries } = inspected;
  const edits = [];
  const additions = [];
  const syncProperties = mergeSyncProperties(content, metadata);
  for (const key of Object.keys(metadata).filter(isSyncField)) {
    const entry = entries[key.toLowerCase()];
    ensure(entry, `Missing/quoted/stale YAML property: ${key}`);
    const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
    edits.push({ ...entry, replacement: [
      ...(entry.comment ? [`${entry.comment}${block.eol}`] : []), ...comments,
    ] });
  }
  for (const [key, value] of Object.entries(updates)) {
    ensure(knownFields().includes(key) && key !== 'kindle-sync', `Unmanaged property: ${key}`);
    if (isSyncField(key)) {
      const previous = Object.keys(syncProperties).find(name => name.toLowerCase() === key.toLowerCase());
      syncProperties[previous || key] = value;
      continue;
    }
    if (JSON.stringify(inspected.values[key]) === JSON.stringify(value)) continue;
    const entry = entries[key];
    const encoded = JSON.stringify(value);
    ensure(encoded !== undefined, 'Undefined update value.');
    if (entry) {
      const comments = lines.slice(entry.start + 1, entry.end).filter(line => /^\s*(?:#.*)?$/.test(line));
      edits.push({ ...entry, replacement: [
        `${entry.spelling}: ${encoded}${entry.comment ? ' ' + entry.comment : ''}${block.eol}`, ...comments,
      ] });
    } else additions.push(`${key}: ${encoded}${block.eol}`);
  }
  for (const edit of edits.sort((a, b) => b.start - a.start)) {
    lines.splice(edit.start, edit.end - edit.start, ...edit.replacement);
  }
  const body = lines.join('');
  const separator = additions.length && body && !body.endsWith('\n') ? block.eol : '';
  return writeSyncMetadata(block.prefix + body + separator + additions.join('') + block.closing + block.tail,
    syncProperties);
}

class IdentifierError extends Error {}

function ensureIdentifier(value, message) {
  if (!value) throw new IdentifierError(message);
}

function isbn(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string', 'ISBNs must be text so leading zeroes are preserved.');
  const cleaned = value.replace(/[-\s]/g, '').toUpperCase();
  ensureIdentifier(/^(?:[0-9]{9}[0-9X]|[0-9]{13})$/.test(cleaned), 'Invalid ISBN shape.');
  if (cleaned.length === 10) {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) =>
      sum + (digit === 'X' ? 10 : Number(digit)) * (10 - index), 0) % 11 === 0, 'Invalid ISBN-10 checksum.');
  } else {
    ensureIdentifier([...cleaned].reduce((sum, digit, index) => sum + Number(digit) * (index % 2 ? 3 : 1), 0) % 10 === 0,
      'Invalid ISBN-13 checksum.');
  }
  return cleaned;
}

function isbnVariants(value) {
  if (!value) return [];
  const result = [value];
  if (value.length === 10) {
    const base = '978' + value.slice(0, 9);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (index % 2 ? 3 : 1), 0);
    result.push(base + ((10 - sum % 10) % 10));
  } else if (value.startsWith('978')) {
    const base = value.slice(3, 12);
    const sum = [...base].reduce((total, digit, index) => total + Number(digit) * (10 - index), 0);
    const check = (11 - sum % 11) % 11;
    result.push(base + (check === 10 ? 'X' : check));
  }
  return result;
}

function asin(value) {
  if (empty(value)) return null;
  ensureIdentifier(typeof value === 'string' && /^[A-Z0-9]{10}$/i.test(value.trim()), 'Invalid ASIN.');
  return value.trim().toUpperCase();
}

function catalogIdentifier(value, parser, label, issues) {
  try {
    return parser(value);
  } catch (error) {
    if (!(error instanceof IdentifierError)) throw error;
    issues.push(`${label}: ${error.message} Ignored ${JSON.stringify(value)}; no identifier was guessed.`);
    return null;
  }
}

function catalogEdition(source, bookId, issues) {
  for (const key of ['id', 'book_id', 'asin', 'isbn_10', 'isbn_13']) {
    ensure(Object.hasOwn(source, key), `Hardcover omitted edition field ${key}.`);
  }
  ensure(source.book_id === bookId, 'Catalog edition belongs to another book.');
  positiveId(source.id, 'catalog edition ID');
  const label = `Hardcover book ${bookId}, edition ${source.id}`;
  return { ...source,
    isbn_10: catalogIdentifier(source.isbn_10, isbn, `${label}, isbn_10`, issues),
    isbn_13: catalogIdentifier(source.isbn_13, isbn, `${label}, isbn_13`, issues),
    asin: catalogIdentifier(source.asin, asin, `${label}, asin`, issues) };
}

function identity(note) {
  const meta = note.meta;
  const source = meta['kindle-sync'] || {};
  const bodyAsin = /^\* ASIN:\s*(\S+)/m.exec(parts(note.content).tail)?.[1];
  const asins = [...new Set([meta.asin, source.asin, meta['kindle-asin'], bodyAsin]
    .filter(value => !empty(value)).map(asin))];
  ensure(asins.length <= 1, `${note.path}: conflicting ASINs.`);
  let authors = meta.author;
  if (empty(authors)) authors = source.author || meta['kindle-author'];
  if (typeof authors === 'string') authors = authors.replace(/^von\s+/i, '').split(/,\s*(?:and\s+)?|\s+(?:and|und)\s+/i);
  ensure(empty(authors) || (Array.isArray(authors) && authors.every(value => typeof value === 'string')),
    `${note.path}: invalid author property.`);
  const filenameTitle = note.path.split('/').at(-1).slice(0, -3).split(' - ').slice(1).join(' - ');
  const heading = /^# ([^\r\n]+)/m.exec(parts(note.content).tail)?.[1];
  const title = !empty(meta.title) ? meta.title : heading || filenameTitle || source.title || meta['kindle-title'];
  ensure(empty(title) || typeof title === 'string', `${note.path}: invalid title.`);
  return { id: empty(meta.hardcover_id) ? null : positiveId(meta.hardcover_id, 'hardcover_id'),
    isbn: isbn(meta.isbn), asin: asins[0] || null, authors: authors || [], title: title || '' };
}

function renderNew(template, book, fields, config) {
  const replacements = {
    'date:YYYY-MM-DD': config.today,
    'VALUE:book_author': authorText(book.authors),
    'VALUE:book_authors': authorText(book.authors),
    'VALUE:book_title': book.title,
    'VALUE:main_topic': '',
  };
  const substitute = (value, markdown = false) => {
    if (typeof value === 'string') {
      const result = value.replace(/\{\{([^{}]+)\}\}/g, (match, name) => {
        ensure(Object.hasOwn(replacements, name), `Unsupported book-template placeholder: ${match}`);
        const replacement = replacements[name];
        return markdown && name.startsWith('VALUE:book_') ?
          replacement.replace(/[\\`*_\[\]<>]/g, '\\$&') : replacement;
      });
      ensure(!/\{\{|\}\}|<%/.test(result), 'Unsupported dynamic book-template syntax.');
      return result;
    }
    if (Array.isArray(value)) return value.map(item => substitute(item, markdown)).filter(value => value !== '');
    if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, substitute(item, markdown)]));
    return value;
  };
  const block = parts(template.content);
  const values = Object.fromEntries(Object.entries(template.frontmatter)
    .filter(([key]) => key !== 'position' || /^position:/m.test(block.yaml))
    .filter(([key]) => !isSyncField(key))
    .map(([key, value]) => [key, substitute(value)]));
  values.created = config.today;
  Object.assign(values, Object.fromEntries(Object.entries(fields).filter(([key]) => !isSyncField(key))));
  if (!book.authors.length) values.author = [];
  const yaml = Object.entries(values).map(([key, value]) => {
    ensure(/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key), 'New-note template keys must be standard unquoted property names.');
    return `${key}: ${JSON.stringify(value)}${block.eol}`;
  }).join('');
  const bodyTemplate = book.authors.length ? block.tail :
    block.tail.replace(/\{\{VALUE:book_authors?\}\}[ \t]+-[ \t]+(?=\{\{VALUE:book_title\}\})/g, '');
  return writeSyncMetadata(`${block.prefix}${yaml}${block.closing}${substitute(bodyTemplate, true)}`,
    { ...mergeSyncProperties(template.content, template.frontmatter),
      ...Object.fromEntries(Object.entries(fields).filter(([key]) => isSyncField(key))) });
}

function filename(book, config) {
  const name = book.authors.length ? `${authorText(book.authors)} - ${book.title}` : book.title;
  const stem = name.normalize('NFC')
    .replace(/[\\/:*?"<>|#^\[\]]/g, ' - ').replace(/\s+/g, ' ').replace(/[. ]+$/, '').trim();
  ensure(stem && encodeURIComponent(`${stem}.md`).replace(/%[0-9A-F]{2}/gi, 'x').length <= 240,
    'Generated book filename is too long; create a shorter note with hardcover_id in its external-sync comment.');
  return `${config.booksFolder}/${stem}.md`;
}

function planLibrary(state, lookups) {
  const books = new Map(state.books.map(book => [book.id, book]));
  const bindings = new Map();
  const conflicts = [];
  const unmatched = [];
  const editions = new Map();
  const looseNotes = [];
  for (const note of state.notes) {
    if (!empty(note.meta.hardcover_user_id) && positiveId(note.meta.hardcover_user_id, 'stored user ID') !== state.userId) {
      conflicts.push({ path: note.path, reason: 'Note is bound to a different Hardcover account.' });
      continue;
    }
    const identity = note.identity;
    let candidates = [];
    const matches = lookups.get(note.path) || [];
    if (identity.id) {
      candidates = books.has(identity.id) ? [identity.id] : [];
      if (matches.length && !matches.some(match => [match.id, match.canonical_id].includes(identity.id))) {
        conflicts.push({ path: note.path, reason: 'hardcover_id disagrees with edition identifiers.' });
        continue;
      }
      if (!books.has(identity.id)) {
        unmatched.push(note);
        continue;
      }
    } else if (matches.length) {
      const ids = [...new Set(matches.map(match => match.canonical_id || match.id))];
      if (ids.length > 1) {
        conflicts.push({ path: note.path, reason: 'ISBN/ASIN resolves to multiple books; set hardcover_id in the external-sync comment.' });
        continue;
      }
      candidates = ids.filter(id => books.has(id));
      if (!candidates.length) {
        unmatched.push(note);
        continue;
      }
    } else {
      const noteAuthors = authorKeys(identity.authors);
      const titleMatches = state.books.filter(book =>
        book.titles.some(title => titleKey(title) === titleKey(identity.title)));
      candidates = titleMatches.filter(book => noteAuthors.length &&
        JSON.stringify(authorKeys(book.authors)) === JSON.stringify(noteAuthors)).map(book => book.id);
      if (!candidates.length && titleMatches.length) {
        conflicts.push({ path: note.path, reason: 'Matching title but different/missing author credits; set hardcover_id in the external-sync comment.' });
        continue;
      }
    }
    if (candidates.length > 1) {
      conflicts.push({ path: note.path, reason: 'Multiple matching library books; set hardcover_id in the external-sync comment.' });
      continue;
    }
    if (!candidates.length) {
      unmatched.push(note);
      looseNotes.push(note);
      continue;
    }
    const id = candidates[0];
    if (bindings.has(id)) {
      conflicts.push({ path: note.path, reason: `Two notes map to Hardcover book ${id}; consolidate or correct their IDs.` });
      continue;
    }
    bindings.set(id, note);
    const matched = matches.find(match => [match.id, match.canonical_id].includes(id));
    if (matched?.editions?.length === 1) editions.set(id, matched.editions[0]);
  }
  const paths = new Map(state.notes.map(note => [note.path.normalize('NFC').toLowerCase(), note.path]));
  const output = [];
  for (const book of state.books) {
    const note = bindings.get(book.id);
    if (!note && !state.config.createMissingNotes) continue;
    if (!note) {
      const similar = looseNotes.filter(candidate => {
        const names = new Set(authorKeys(candidate.identity.authors));
        return authorKeys(book.authors).some(name => names.has(name));
      });
      if (similar.length) {
        conflicts.push({ bookId: book.id, reason: `Possible alternate-title/edition match: ${similar.map(item => item.path).join(', ')}. Bind IDs before creating.` });
        continue;
      }
    }
    let notePath;
    if (note) notePath = note.path;
    else {
      try {
        notePath = filename(book, state.config);
      } catch (error) {
        conflicts.push({ bookId: book.id, reason: error.message });
        continue;
      }
      const key = notePath.normalize('NFC').toLowerCase();
      if (paths.has(key)) {
        conflicts.push({ bookId: book.id, path: notePath, reason: 'New filename collides with an existing/planned note; bind IDs or disambiguate manually.' });
        continue;
      }
      paths.set(key, notePath);
    }
    const meta = note?.meta || {};
    const fields = {
      status: book.status, rating: book.rating, started: book.started, finished: book.finished,
      hardcover_finished_precision: book.precision, hardcover_id: book.id,
      hardcover_user_id: state.userId, hardcover_user_book_id: book.userBookId,
      hardcover_url: book.url, hardcover_added: book.added,
      hardcover_edition_id: book.edition?.id || null,
    };
    const issues = [...new Set([...(book.issues || []),
      ...(note ? (lookups.get(note.path) || []).flatMap(match => match.issues || []) : [])])];
    if (!book.authors.length) {
      issues.push('Hardcover has no primary-author credits. Empty author metadata stays blank and will be filled when source authors become available; existing values are preserved.');
    }
    if (!book.url) issues.push('Hardcover has no URL slug; the link remains unknown.');
    const selected = note && (note.identity.asin || note.identity.isbn) ? editions.get(book.id) : book.edition;
    const fill = {
      title: book.title, author: book.authors.map(name => `[[${name}]]`), source: book.url,
      isbn: selected?.isbn_13 || selected?.isbn_10 || null, asin: selected?.asin || null,
      category: book.category,
    };
    for (const [key, value] of Object.entries(fill)) {
      if (empty(meta[key]) && !empty(value)) fields[key] = value;
    }
    if (note && !selected && (empty(meta.isbn) || empty(meta.asin))) {
      issues.push('Edition identifiers were not guessed from a different Hardcover edition.');
    }
    const proposed = note ? splice(note.content, note.frontmatter, fields) :
      renderNew(state.template, book, fields, state.config);
    const changes = {};
    for (const [key, value] of Object.entries(fields)) {
      if (JSON.stringify(meta[key]) !== JSON.stringify(value)) changes[key] = { before: meta[key] ?? null, after: value };
    }
    const headers = { 'Content-Type': 'text/markdown' };
    if (note) headers['If-Match'] = note.version;
    else headers['If-None-Match'] = '*';
    output.push({ config: state.config, bookId: book.id, path: notePath, changes, issues, headers,
      url: noteUrl(state.config, notePath), proposedContent: proposed,
      action: note ? proposed === note.content ? 'unchanged' : 'update' : 'create' });
  }
  for (const note of unmatched) {
    output.push({ config: state.config, path: note.path, action: 'not-in-library', changes: {},
      issues: [...(lookups.get(note.path) || []).flatMap(match => match.issues || []),
        'No unambiguous book in this Hardcover library; existing note is untouched.'] });
  }
  if (conflicts.length && !state.config.previewOnly) {
    throw new Error(`No writes planned: resolve ${conflicts.length} identity conflict(s) in a preview first. ${JSON.stringify(conflicts)}`);
  }
  for (const item of output) item.blockers = conflicts;
  for (const conflict of conflicts) output.push({
    config: state.config, action: 'conflict', ...conflict, issues: [conflict.reason], blockers: conflicts, changes: {},
  });
  return output.length ? output : [{ config: state.config, action: 'empty-library', issues: [],
    changes: {}, blockers: [], note: 'Hardcover returned no library books; nothing was changed.' }];
}

return (function verify() {
  const expected = $('Write enabled?').all(0);
  const actual = $input.all();
  ensure(expected.length === actual.length, 'Unexpected read-back response count.');
  return actual.map((response, index) => {
    const plan = expected[index].json;
    const body = httpBody(response.json, `Obsidian read-back ${plan.path}`);
    ensure(body === plan.proposedContent,
      `${plan.path}: persisted content differs from the proposal; inspect concurrent/Seafile edits before rerunning.`);
    return { json: { path: plan.path, bookId: plan.bookId, action: plan.action,
      verified: true, changes: plan.changes, issues: plan.issues } };
  });
})();
